		}
		writeJSON(records)
	default:
		fmt.Fprintf(os.Stderr, "unknown alerts subcommand %q\n", args[0])
		usage()
		os.Exit(2)
	}
}

func runSuppressions(args []string) {
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "usage: mevwatch suppressions <list|register|revoke> ...")
		os.Exit(2)
	}
	switch args[0] {
	case "list":
