package mevwatch

import (
	"math"
	"reflect"
	"testing"
)

func TestScratchDetectScenarios(t *testing.T) {
	base := []Swap{
		{TxHash: "f", Pool: "P", Trader: "bot", GasPrice: 90, Index: 0},
		{TxHash: "o1", Pool: "Q", Trader: "q1", GasPrice: 9999, Index: 1},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 2},
		{TxHash: "o2", Pool: "Q", Trader: "q2", GasPrice: 9999, Index: 3},
		{TxHash: "b", Pool: "P", Trader: "bot", GasPrice: 80, Index: 4},
	}
	perms := [][]int{
		{0, 1, 2, 3, 4}, {4, 3, 2, 1, 0}, {1, 0, 3, 4, 2},
		{2, 0, 1, 4, 3}, {3, 1, 4, 2, 0}, {1, 3, 0, 2, 4},
	}
	for pi, perm := range perms {
		swaps := make([]Swap, len(perm))
		for i, j := range perm {
			swaps[i] = base[j]
		}
		got := Detect(swaps, "v")
		if len(got) != 1 || got[0].Kind != "sandwich" || got[0].Severity != 3 {
			t.Fatalf("perm %d: want sandwich, got %+v", pi, got)
		}
		wantEv := []string{
			"front-run by bot at gas 90",
			"back-run by bot at gas 80",
			"victim gas 12",
		}
		if !reflect.DeepEqual(got[0].Evidence, wantEv) {
			t.Fatalf("perm %d evidence: %v", pi, got[0].Evidence)
		}
		if !reflect.DeepEqual(swaps, func() []Swap {
			out := make([]Swap, len(perm))
			for i, j := range perm {
				out[i] = base[j]
			}
			return out
		}()) {
			t.Fatalf("perm %d: input mutated", pi)
		}
	}

	// Other-pool high-gas tx must not become evidence: victim is last in P,
	// same-pool predecessor has equal/low gas -> no conclusion.
	otherPool := []Swap{
		{TxHash: "o1", Pool: "Q", Trader: "q", GasPrice: 9999, Index: 0},
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: 12, Index: 1},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 2},
	}
	if got := Detect(otherPool, "v"); got != nil {
		t.Fatalf("other-pool gas leaked: %+v", got)
	}

	// Other-pool tx physically bracketing must not form a sandwich even with
	// same trader; same-pool predecessor does not dominate either.
	cross := []Swap{
		{TxHash: "x1", Pool: "Q", Trader: "bot", GasPrice: 9999, Index: 1},
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: 12, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 2},
		{TxHash: "x2", Pool: "Q", Trader: "bot", GasPrice: 9999, Index: 3},
	}
	if got := Detect(cross, "v"); got != nil {
		t.Fatalf("cross-pool bracket leaked: %+v", got)
	}

	// Last swap in pool still judged for displacement.
	last := []Swap{
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: 30, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 2},
	}
	got := Detect(last, "v")
	if len(got) != 1 || got[0].Kind != "displacement" || got[0].Severity != 2 {
		t.Fatalf("last-in-pool displacement: %+v", got)
	}

	// Exactly 2x is not strict -> no conclusion.
	exact := []Swap{
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: 24, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 1},
	}
	if got := Detect(exact, "v"); got != nil {
		t.Fatalf("exact 2x hit: %+v", got)
	}

	// Zero victim gas, positive front gas -> displacement.
	zero := []Swap{
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: 1, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 0, Index: 1},
	}
	if got := Detect(zero, "v"); len(got) != 1 || got[0].Kind != "displacement" {
		t.Fatalf("zero victim gas: %+v", got)
	}

	// Near MaxInt64: victim high, front MaxInt64 — 2x would overflow; the
	// true ratio is below 2, so no conclusion.
	big := []Swap{
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: math.MaxInt64, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: math.MaxInt64 - 1, Index: 1},
	}
	if got := Detect(big, "v"); got != nil {
		t.Fatalf("overflow false positive: %+v", got)
	}
	// True >2x near the limit still hits: MaxInt64 > (MaxInt64/3)*2.
	bigHit := []Swap{
		{TxHash: "f", Pool: "P", Trader: "fr", GasPrice: math.MaxInt64, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: math.MaxInt64 / 3, Index: 1},
	}
	if got := Detect(bigHit, "v"); len(got) != 1 || got[0].Kind != "displacement" {
		t.Fatalf("near-limit true 2x missed: %+v", got)
	}

	// Missing tx and first-in-pool -> nil.
	if got := Detect(base, "nope"); got != nil {
		t.Fatalf("missing tx: %+v", got)
	}
	if got := Detect(base, "f"); got != nil {
		t.Fatalf("first in pool: %+v", got)
	}

	// Sandwich takes priority over displacement.
	prio := []Swap{
		{TxHash: "f", Pool: "P", Trader: "bot", GasPrice: 900, Index: 0},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 1},
		{TxHash: "b", Pool: "P", Trader: "bot", GasPrice: 800, Index: 2},
	}
	if got := Detect(prio, "v"); len(got) != 1 || got[0].Kind != "sandwich" {
		t.Fatalf("priority: %+v", got)
	}

	// Agreement with DetectBlock across many permutations of a mixed block.
	mixed := []Swap{
		{TxHash: "f", Pool: "P", Trader: "bot", GasPrice: 90, Index: 0},
		{TxHash: "q0", Pool: "Q", Trader: "qq", GasPrice: 5, Index: 1},
		{TxHash: "v", Pool: "P", Trader: "user", GasPrice: 12, Index: 2},
		{TxHash: "q1", Pool: "Q", Trader: "zz", GasPrice: 1, Index: 3},
		{TxHash: "b", Pool: "P", Trader: "bot", GasPrice: 80, Index: 4},
		{TxHash: "w", Pool: "P", Trader: "user2", GasPrice: 3, Index: 5},
	}
	block := DetectBlock(mixed)
	byTx := map[string]ReportFinding{}
	for _, f := range block {
		byTx[f.TxHash] = f
	}
	for _, order := range [][]int{
		{0, 1, 2, 3, 4, 5}, {5, 4, 3, 2, 1, 0}, {1, 3, 5, 2, 4, 0}, {3, 0, 4, 1, 5, 2},
	} {
		shuffled := make([]Swap, len(order))
		for i, j := range order {
			shuffled[i] = mixed[j]
		}
		for _, s := range mixed {
			got := Detect(shuffled, s.TxHash)
			want, expected := byTx[s.TxHash]
			if !expected {
				if got != nil {
					t.Fatalf("tx %s: block says none, Detect says %+v", s.TxHash, got)
				}
				continue
			}
			if len(got) != 1 || got[0].Kind != want.Kind || got[0].Severity != want.Severity {
				t.Fatalf("tx %s: mismatch block=%+v detect=%+v", s.TxHash, want, got)
			}
		}
	}
}

